#!/usr/bin/env python3
"""Creator OS — local-first content operations server.
Build 02 adds a persistent research vault, discovery connectors, source ingestion,
claim candidates, and provenance-first research contracts. No third-party Python
packages are required. Optional Ollama and YouTube Data API integrations.
"""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs
from urllib.request import Request, urlopen
import json, sqlite3, os, datetime, re
from research_engine import discover, fetch_page, extract_claim_candidates, research_contract as research_contract_v2
ROOT=os.path.dirname(os.path.abspath(__file__));DB=os.path.join(ROOT,'creator_os.db');PORT=int(os.getenv('PORT','8787'));OLLAMA_URL=os.getenv('OLLAMA_BASE_URL','http://127.0.0.1:11434');OLLAMA_MODEL=os.getenv('OLLAMA_MODEL','qwen2.5:7b')
def db():
 c=sqlite3.connect(DB);c.row_factory=sqlite3.Row;c.executescript('''CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,name TEXT,kind TEXT,language TEXT,cadence TEXT,color TEXT);CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,angle TEXT,score INTEGER,demand INTEGER,competition INTEGER,originality INTEGER,researchability INTEGER,status TEXT,created_at TEXT);CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,channel_id TEXT,kind TEXT,status TEXT,stage TEXT,progress INTEGER,updated_at TEXT,error TEXT);CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,url TEXT,title TEXT,source_type TEXT,trust INTEGER,notes TEXT);CREATE TABLE IF NOT EXISTS claims(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,claim TEXT,source_id INTEGER,confidence INTEGER,status TEXT,conflict TEXT,notes TEXT);CREATE TABLE IF NOT EXISTS discoveries(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,query TEXT,payload TEXT,created_at TEXT);''')
 if c.execute('SELECT COUNT(*) n FROM channels').fetchone()['n']==0:c.executemany('INSERT INTO channels VALUES(?,?,?,?,?,?)',[('bgmi','BGMI Live','gaming','Hindi','3 lives / week','#f59e0b'),('kids','Hindi Kids Stories','kids','Hindi','5 videos / week','#22c55e'),('history','Itihas Uncovered','documentary','Hindi','2 documentaries / week','#a78bfa'),('tech','Tech Explained Hindi','tech','Hindi','2 videos / week','#38bdf8'),('blog','Research Desk','blog','Hindi + English','Daily','#fb7185')])
 if c.execute('SELECT COUNT(*) n FROM topics').fetchone()['n']==0:c.executemany('INSERT INTO topics(title,angle,score,demand,competition,originality,researchability,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[('Battle of Panipat','The logistics, alliances and decisions that shaped the outcome before the main clash',92,91,76,94,97,'approved','2026-09-14'),('Nalanda: What Actually Happened?','Separate the popular destruction narrative from what primary and scholarly sources support',89,88,82,91,95,'candidate','2026-09-14'),('How UPI Became India’s Invisible Infrastructure','The technical and economic story behind India’s real-time payments scale',87,86,71,88,96,'candidate','2026-09-14'),('Subhas Chandra Bose: The Part of the Story We Skip','A source-led timeline of strategy, alliances and unresolved historical questions',85,87,81,90,93,'candidate','2026-09-14')])
 c.commit();return c
def now():return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
def rows(c,q,args=()):return [dict(x) for x in c.execute(q,args).fetchall()]
def ollama(prompt):
 try:
  payload=json.dumps({'model':OLLAMA_MODEL,'prompt':prompt,'stream':False}).encode();req=Request(OLLAMA_URL+'/api/generate',data=payload,headers={'Content-Type':'application/json'})
  with urlopen(req,timeout=90) as r:return json.loads(r.read()).get('response','')
 except Exception:return ''
def research_contract(topic):return research_contract_v2(topic)
HTML='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Creator OS</title><style>:root{--bg:#07090d;--p:#0d1118;--p2:#111722;--line:#1d2633;--text:#f5f7fb;--muted:#8d9aac;--a:#8b5cf6;--good:#34d399}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.app{display:flex;min-height:100vh}.side{width:235px;background:#090c12;border-right:1px solid var(--line);padding:18px 14px;position:fixed;inset:0 auto 0 0}.brand{font-size:19px;font-weight:700;padding:12px}.brand b{color:#b99cff}.nav button{width:100%;background:none;border:0;color:#9aa6b8;text-align:left;padding:11px 12px;border-radius:10px;cursor:pointer}.nav button:hover,.nav button.active{background:#ffffff08;color:#fff}.bottom{position:absolute;bottom:18px;left:14px;right:14px}.main{margin-left:235px;flex:1;padding:30px;max-width:1500px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}h1{font-size:32px;margin:8px 0 5px}h2{font-size:18px;margin:0}.muted{color:var(--muted)}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(4,1fr);margin-top:26px}.cols{grid-template-columns:1.35fr .65fr;margin-top:14px}.panel{background:var(--p);border:1px solid var(--line);border-radius:17px;padding:18px}.metric{min-height:108px}.metric .v{font-size:28px;font-weight:700;margin-top:8px}.btn{border:1px solid var(--line);background:#111722;color:#fff;border-radius:10px;padding:9px 13px;cursor:pointer}.primary{background:var(--a);border-color:var(--a)}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.job,.topic,.channel{background:var(--p2);border:1px solid var(--line);border-radius:13px;padding:13px}.list{display:grid;gap:8px;margin-top:14px}.badge{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:4px 8px;color:#aab4c4}.bar{height:5px;background:#ffffff09;border-radius:20px;overflow:hidden}.bar i{display:block;height:100%;background:var(--a);border-radius:20px}.score{font-size:21px;color:#b99cff;font-weight:700}.topicgrid{grid-template-columns:repeat(2,1fr);margin-top:14px}.mini{font-size:11px;color:var(--muted)}input{width:100%;background:#080b10;color:#fff;border:1px solid var(--line);border-radius:10px;padding:11px;outline:none}input:focus{border-color:#7c3aed}.studio{margin-top:22px}.hidden{display:none}.result{white-space:pre-wrap;font:12px ui-monospace,monospace;color:#aeb8c7;background:#080b10;border:1px solid var(--line);padding:13px;border-radius:10px;max-height:420px;overflow:auto}@media(max-width:900px){.side{display:none}.main{margin-left:0;padding:18px}.metrics,.cols,.topicgrid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.metrics,.cols,.topicgrid{grid-template-columns:1fr}}</style></head><body><div class="app"><aside class="side"><div class="brand">Creator<b>OS</b><div class="mini" style="margin-top:4px">local content operating system</div></div><div class="nav"><button class="active" onclick="show('dashboard',this)">◈ Dashboard</button><button onclick="show('studio',this)">✦ Production Studio</button><button onclick="show('topics',this)">⌁ Topic Lab</button><button onclick="show('channels',this)">◉ Channels</button><button onclick="show('research',this)">▤ Research Vault</button><button onclick="show('analytics',this)">◫ Analytics</button><button onclick="show('blog',this)">✎ Blog</button></div><div class="bottom panel"><div class="mini">LOCAL ENGINE</div><div style="margin-top:8px"><span style="color:var(--good)">●</span> Research engine online</div><div class="mini" style="margin-top:4px">Ollama + YouTube are optional connectors.</div></div></aside><main class="main"><section id="dashboard"><div class="top"><div><div class="eyebrow">Creator command center</div><h1>Build once. Publish everywhere.</h1><div class="muted">Demand-led research → original production → QA → human approval.</div></div><button class="btn primary" onclick="show('studio')">＋ New production</button></div><div class="grid metrics"><div class="panel metric"><div class="eyebrow">Active channels</div><div class="v">4</div><div class="mini">+ blog engine</div></div><div class="panel metric"><div class="eyebrow">Research sources</div><div class="v" id="sourceMetric">—</div><div class="mini">local evidence vault</div></div><div class="panel metric"><div class="eyebrow">Claim candidates</div><div class="v" id="claimMetric">—</div><div class="mini">verification required</div></div><div class="panel metric"><div class="eyebrow">Publishing gate</div><div class="v">ON</div><div class="mini">human approval required</div></div></div><div class="grid cols"><div class="panel"><div class="row between"><div><h2>Production queue</h2><div class="mini" style="margin-top:4px">Research is the first hard gate.</div></div><span class="badge">provenance ON</span></div><div id="jobs" class="list"></div></div><div class="panel"><h2>Channel health</h2><div id="channels" class="list"></div></div></div></section><section id="studio" class="hidden"><div class="eyebrow">Production studio</div><h1>Start a production</h1><div class="muted">Create the evidence contract before script generation.</div><div class="panel studio"><label class="mini">TOPIC</label><div class="row" style="margin-top:8px"><input id="topicInput" value="Battle of Panipat"><button class="btn primary" onclick="plan()">Create plan</button></div><div id="planOut" style="margin-top:14px"></div></div></section><section id="topics" class="hidden"><div class="eyebrow">Topic lab</div><h1>Find the next video</h1><div class="muted">Prioritize demand without cloning competitors.</div><div id="topicList" class="grid topicgrid"></div></section><section id="channels" class="hidden"><div class="eyebrow">Channels</div><h1>Channel portfolio</h1><div id="channelList" class="list"></div></section><section id="research" class="hidden"><div class="eyebrow">Research vault</div><h1>Evidence before narration</h1><div class="muted">Discovery finds signals; ingestion creates local evidence records. Claims stay untrusted until reviewed.</div><div class="panel studio"><div class="row"><input id="researchQ" value="Battle of Panipat"><button class="btn primary" onclick="discoverResearch()">Discover</button></div><div id="researchOut" class="list"></div></div><div class="panel studio"><div class="row"><input id="sourceUrl" placeholder="Paste an authoritative source URL"><button class="btn" onclick="ingestSource()">Ingest source</button></div><div id="ingestOut" style="margin-top:12px"></div></div><div class="panel studio"><div class="row between"><div><h2>Claim ledger</h2><div class="mini">Baseline extraction marks claims as needs_review.</div></div><span class="badge">provenance ON</span></div><div id="claimsOut" class="list"></div></div></section><section id="analytics" class="hidden"><div class="eyebrow">Analytics</div><h1>Learn what the audience rewards</h1><div class="panel studio"><p class="muted">The YouTube Analytics connector will turn retention, views, likes, subscribers and traffic sources into production feedback.</p></div></section><section id="blog" class="hidden"><div class="eyebrow">Research Desk</div><h1>One research project, many outputs</h1><div class="panel studio"><div class="row between"><div><b>Master research package</b><div class="muted" style="margin-top:4px">Documentary + Shorts + article + social derivatives.</div></div><span class="badge">source-linked</span></div><div class="list"><div class="job">Article brief → evidence-backed long-form</div><div class="job">FAQ + structured internal links</div><div class="job">Shorts candidates from original narrative</div><div class="job">Thumbnail concepts tied to the actual story</div></div></div></section></main></div><script>const ids=['dashboard','studio','topics','channels','research','analytics','blog'];window.activeTopicId=0;function show(id,btn){ids.forEach(x=>document.getElementById(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');if(id==='topics')loadTopics();if(id==='channels')loadChannels();if(id==='research')loadClaims()}async function j(u,o){let r=await fetch(u,o);return r.json()}function esc(x){return String(x||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}async function loadJobs(){let d=await j('/api/jobs');document.getElementById('jobs').innerHTML=d.jobs.map(x=>`<div class="job"><div class="row between"><div><b>${esc(x.title)}</b><div class="mini" style="margin-top:4px">${esc(x.kind)} · ${esc(x.stage)} · ${esc(x.updated_at)}</div></div><span class="badge">${esc(x.status)}</span></div><div class="bar" style="margin-top:10px"><i style="width:${x.progress}%"></i></div></div>`).join('')}async function loadChannels(){let d=await j('/api/channels');document.getElementById('channelList').innerHTML=d.channels.map(x=>`<div class="channel row"><div style="font-size:22px">${x.kind==='gaming'?'🎮':x.kind==='kids'?'🧒':x.kind==='documentary'?'📚':x.kind==='tech'?'🤖':'✎'}</div><div style="flex:1"><b>${esc(x.name)}</b><div class="mini">${esc(x.language)} · ${esc(x.cadence)}</div></div><span class="badge">ready</span></div>`).join('');document.getElementById('channels').innerHTML=d.channels.slice(0,4).map(x=>`<div class="channel row"><div style="font-size:20px">${x.kind==='gaming'?'🎮':x.kind==='kids'?'🧒':x.kind==='documentary'?'📚':'🤖'}</div><div style="flex:1"><b>${esc(x.name)}</b><div class="mini">${esc(x.cadence)}</div></div><span style="color:var(--good);font-size:11px">healthy</span></div>`).join('')}async function loadTopics(){let d=await j('/api/topics');document.getElementById('topicList').innerHTML=d.topics.map(x=>`<div class="topic"><div class="row between"><div><b>${esc(x.title)}</b><div class="mini" style="margin-top:5px;line-height:1.5">${esc(x.angle)}</div></div><div class="score">${x.score}</div></div><div class="grid" style="grid-template-columns:repeat(4,1fr);gap:7px;margin-top:14px">${[['Demand',x.demand],['Originality',x.originality],['Research',x.researchability],['Competition',x.competition]].map(a=>`<div><div class="mini">${a[0]}</div><div class="bar" style="margin-top:5px"><i style="width:${a[1]}%"></i></div></div>`).join('')}</div><div class="row between" style="margin-top:13px"><span class="badge">${x.source_count} sources</span><span class="mini">${esc(x.status)}</span></div></div>`).join('')}async function plan(){let t=document.getElementById('topicInput').value.trim();if(!t)return;let out=document.getElementById('planOut');out.innerHTML='<div class="muted">Creating production contract…</div>';let d=await j('/api/plan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:t})});window.activeTopicId=d.topic_id||0;out.innerHTML='<div class="result">'+esc(JSON.stringify(d,null,2))+'</div>'}async function discoverResearch(){let q=document.getElementById('researchQ').value.trim();if(!q)return;let out=document.getElementById('researchOut');out.innerHTML='<div class="muted">Collecting discovery signals…</div>';let d=window.activeTopicId?await j('/api/research/discover',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic_id:window.activeTopicId,q:q})}):await j('/api/research/discover?q='+encodeURIComponent(q));if(d.error){out.innerHTML='<div class="result">'+esc(d.error)+'</div>';return}out.innerHTML=d.items.map(x=>`<div class="job"><div class="row between"><div><b>${esc(x.title||'Untitled')}</b><div class="mini">${esc(x.kind||'source')} · ${esc(x.channel||x.published||'')}</div></div><span class="badge">signal ${x.signal||0}</span></div>${x.url?`<div class="mini" style="margin-top:7px;word-break:break-all">${esc(x.url)}</div>`:''}</div>`).join('')}async function ingestSource(){let u=document.getElementById('sourceUrl').value.trim();if(!u)return;let out=document.getElementById('ingestOut');if(!window.activeTopicId){out.innerHTML='<div class="muted">Create a production plan first.</div>';return}out.innerHTML='<div class="muted">Fetching and extracting candidate claims…</div>';let d=await j('/api/research/ingest',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic_id:window.activeTopicId,url:u})});out.innerHTML='<div class="result">'+esc(JSON.stringify(d,null,2))+'</div>';loadClaims()}async function loadClaims(){if(!window.activeTopicId)return;let d=await j('/api/research/claims?topic_id='+window.activeTopicId);document.getElementById('claimsOut').innerHTML=d.claims.map(x=>`<div class="job"><b>${esc(x.claim)}</b><div class="mini" style="margin-top:7px">confidence ${x.confidence} · ${esc(x.status)} · ${esc(x.source_title||'source')}</div></div>`).join('')||'<div class="muted">No claims yet.</div>'}loadJobs();loadChannels();</script></body></html>'''
class H(BaseHTTPRequestHandler):
 def send_json(self,data,status=200):
  b=json.dumps(data,ensure_ascii=False).encode();self.send_response(status);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  p=urlparse(self.path).path;c=db()
  if p=='/':b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
  if p=='/api/health':self.send_json({'ok':True,'ollama':bool(ollama('Reply only OK')=='OK'),'model':OLLAMA_MODEL,'youtube_api_configured':bool(os.getenv('YOUTUBE_API_KEY'))});return
  if p=='/api/channels':self.send_json({'channels':rows(c,'SELECT * FROM channels ORDER BY rowid')});return
  if p=='/api/topics':self.send_json({'topics':rows(c,'SELECT t.*,COUNT(s.id) source_count FROM topics t LEFT JOIN sources s ON s.topic_id=t.id GROUP BY t.id ORDER BY score DESC')});return
  if p=='/api/jobs':self.send_json({'jobs':rows(c,'SELECT * FROM jobs ORDER BY id DESC')});return
  if p=='/api/research/claims':
   tid=int(parse_qs(urlparse(self.path).query).get('topic_id',['0'])[0] or 0);self.send_json({'claims':rows(c,'SELECT claims.*,sources.url,sources.title source_title FROM claims LEFT JOIN sources ON sources.id=claims.source_id WHERE claims.topic_id=? ORDER BY claims.id DESC',(tid,))});return
  if p=='/api/research/sources':
   tid=int(parse_qs(urlparse(self.path).query).get('topic_id',['0'])[0] or 0);self.send_json({'sources':rows(c,'SELECT * FROM sources WHERE topic_id=? ORDER BY id DESC',(tid,))});return
  if p=='/api/research/discover':
   q=parse_qs(urlparse(self.path).query).get('q',[''])[0].strip()
   if not q:return self.send_json({'error':'q required'},400)
   try:self.send_json(discover(q))
   except Exception as e:self.send_json({'error':str(e)},502)
   return
  self.send_json({'error':'not found'},404)
 def do_POST(self):
  p=urlparse(self.path).path;n=int(self.headers.get('Content-Length','0'));raw=self.rfile.read(n);body=json.loads(raw or '{}');c=db()
  if p=='/api/plan':
   topic=str(body.get('topic','')).strip()
   if not topic:return self.send_json({'error':'topic required'},400)
   contract=research_contract(topic);ai=ollama(f'''You are the research director for a Hindi documentary YouTube channel. Topic: {topic}. Produce 5 original angles, audience questions, primary source types, claims to verify, and visual opportunities. Do not imitate any existing creator.''');cur=c.execute('INSERT INTO topics(title,angle,score,demand,competition,originality,researchability,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)',(topic,'Pending research',0,0,0,0,0,'researching',now()));tid=cur.lastrowid;c.commit();self.send_json({'ok':True,'topic_id':tid,'topic':topic,'contract':contract,'local_ai_plan':ai or 'Ollama unavailable — contract created; connect Ollama to generate the AI planning layer.'});return
  if p=='/api/research/discover':
   topic_id=int(body.get('topic_id',0) or 0);q=str(body.get('q','')).strip()
   if not topic_id or not q:return self.send_json({'error':'topic_id and q required'},400)
   try:result=discover(q)
   except Exception as e:return self.send_json({'error':str(e)},502)
   c.execute('INSERT INTO discoveries(topic_id,query,payload,created_at) VALUES(?,?,?,?)',(topic_id,q,json.dumps(result),now()))
   for item in result.get('items',[]):
    if item.get('url'):c.execute('INSERT INTO sources(topic_id,url,title,source_type,trust,notes) VALUES(?,?,?,?,?,?)',(topic_id,item['url'],item.get('title',''),item.get('kind',item.get('source_type','web')),60,'discovery signal; not yet a primary source'))
   c.commit();self.send_json(result);return
  if p=='/api/research/ingest':
   topic_id=int(body.get('topic_id',0) or 0);url=str(body.get('url','')).strip();title=str(body.get('title','')).strip()
   if not topic_id or not url:return self.send_json({'error':'topic_id and url required'},400)
   try:page=fetch_page(url)
   except Exception as e:return self.send_json({'error':str(e)},502)
   cur=c.execute('INSERT INTO sources(topic_id,url,title,source_type,trust,notes) VALUES(?,?,?,?,?,?)',(topic_id,url,title or url,'web',70,'fetched into local research vault'));sid=cur.lastrowid;candidates=extract_claim_candidates(page['text'])
   for claim in candidates:c.execute('INSERT INTO claims(topic_id,claim,source_id,confidence,status,conflict,notes) VALUES(?,?,?,?,?,?,?)',(topic_id,claim,sid,55,'needs_review','unknown','baseline extraction; verify against authoritative sources'))
   c.commit();self.send_json({'ok':True,'source_id':sid,'claims_added':len(candidates),'text_chars':len(page['text'])});return
  self.send_json({'error':'not found'},404)
if __name__=='__main__':db().close();print(f'Creator OS running at http://127.0.0.1:{PORT}');ThreadingHTTPServer(('0.0.0.0',PORT),H).serve_forever()
